218	// parseCodexLines reads all JSONL lines, keeping response_item and
219	// token_count event_msg entries.
220	func parseCodexLines(content []byte) ([]codexLine, error) {
221		reader := bufio.NewReader(bytes.NewReader(content))
222		var lines []codexLine
223	
224		for {
225			lineBytes, err := reader.ReadBytes('\n')
226			if err != nil && err != io.EOF {
227				return nil, fmt.Errorf("reading codex line: %w", err)
228			}
229	
230			if len(bytes.TrimSpace(lineBytes)) > 0 {
231				var cl codexLine
232				if json.Unmarshal(lineBytes, &cl) == nil {
233					if cl.Type == "response_item" || isCodexTokenCountLine(cl) {
234						lines = append(lines, cl)
235					}
236				}
237			}
238	
239			if err == io.EOF {
240				break
241			}
242		}
243		return lines, nil
244	}
245	
246	// isCodexTokenCountLine checks if a codexLine is an event_msg with token_count payload.
247	func isCodexTokenCountLine(cl codexLine) bool {
248		if cl.Type != "event_msg" {
249			return false
250		}
251		var p struct {
252			Type string `json:"type"`
253		}
254		return json.Unmarshal(cl.Payload, &p) == nil && p.Type == "token_count"
255	}
256	
257	// codexTokenCount extracts input/output tokens from a token_count payload.
258	func codexTokenCount(payload json.RawMessage) (input, output int) {
259		var tc struct {
260			InputTokens  int `json:"input_tokens"`
261			OutputTokens int `json:"output_tokens"`
262		}
263		if json.Unmarshal(payload, &tc) == nil {
264			return tc.InputTokens, tc.OutputTokens
265		}
266		return 0, 0
267	}
