269	// codexUserText extracts the actual user prompt text from a Codex user message,
270	// dropping system-injected content (AGENTS.md, environment_context, permissions,
271	// turn_aborted, etc.).
272	func codexUserText(raw json.RawMessage) string {
273		var blocks []struct {
274			Type string `json:"type"`
275			Text string `json:"text"`
276		}
277		if json.Unmarshal(raw, &blocks) != nil {
278			return ""
279		}
