func TestBuildCondensedTranscriptFromBytes_Codex_RealRolloutShape(t *testing.T) {
	t.Parallel()

	// Mirrors the sampleRollout shape from cmd/entire/cli/agent/codex/transcript_test.go.
	// This is the real Codex transcript format with both function_call (exec_command)
	// and custom_tool_call (apply_patch) entries.
	codexTranscript := []byte(`{"timestamp":"2026-03-25T11:31:10.000Z","type":"session_meta","payload":{"id":"s1"}}
{"timestamp":"2026-03-25T11:31:11.000Z","type":"response_item","payload":{"type":"message","role":"developer","content":[{"type":"input_text","text":"system instructions"}]}}
{"timestamp":"2026-03-25T11:31:11.500Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"# AGENTS.md\ninstructions"}]}}
{"timestamp":"2026-03-25T11:31:11.754Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"Create a file called hello.txt"}]}}
{"timestamp":"2026-03-25T11:31:12.000Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":5000,"cached_input_tokens":4000,"output_tokens":100,"reasoning_output_tokens":20,"total_tokens":5120}}}}
{"timestamp":"2026-03-25T11:31:13.000Z","type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":"Creating the file now."}]}}
{"timestamp":"2026-03-25T11:31:14.000Z","type":"response_item","payload":{"type":"custom_tool_call","status":"completed","call_id":"call_1","name":"apply_patch","input":"*** Begin Patch\n*** Add File: hello.txt\n+Hello World\n*** End Patch\n"}}
{"timestamp":"2026-03-25T11:31:14.500Z","type":"response_item","payload":{"type":"custom_tool_call_output","call_id":"call_1","output":{"type":"text","text":"Success. Updated: A hello.txt"}}}
{"timestamp":"2026-03-25T11:31:15.000Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":10000,"cached_input_tokens":8000,"output_tokens":200,"reasoning_output_tokens":50,"total_tokens":10250}}}}
{"timestamp":"2026-03-25T11:31:16.000Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"Now create docs/readme.md too"}]}}
{"timestamp":"2026-03-25T11:31:17.000Z","type":"response_item","payload":{"type":"custom_tool_call","status":"completed","call_id":"call_2","name":"apply_patch","input":"*** Begin Patch\n*** Add File: docs/readme.md\n+# Readme\n*** Update File: hello.txt\n-Hello World\n+Hello World!\n*** End Patch\n"}}
{"timestamp":"2026-03-25T11:31:18.000Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":15000,"cached_input_tokens":12000,"output_tokens":300,"reasoning_output_tokens":80,"total_tokens":15380}}}}
{"timestamp":"2026-03-25T11:31:19.000Z","type":"event_msg","payload":{"type":"task_complete"}}
`)

	entries, err := BuildCondensedTranscriptFromBytes(codexTranscript, agent.AgentTypeCodex)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// Verify we get meaningful entries from this real-world transcript shape.
	if len(entries) == 0 {
		t.Fatal("expected non-empty entries from real Codex rollout shape")
	}

	// Must contain the user prompt (developer/AGENTS.md prompts should be filtered).
	var userEntries, toolEntries, assistantEntries int
	for _, e := range entries {
		switch e.Type {
		case EntryTypeUser:
			userEntries++
		case EntryTypeTool:
			toolEntries++
		case EntryTypeAssistant:
			assistantEntries++
		}
	}

	if userEntries < 2 {
		t.Errorf("expected at least 2 user entries (two prompts), got %d", userEntries)
	}

	// Critical: apply_patch tool calls must appear (this was the main bug).
	if toolEntries < 1 {
		t.Errorf("expected at least 1 tool entry (apply_patch), got %d — apply_patch is being dropped", toolEntries)
	}

	// Verify apply_patch is specifically named.
	foundApplyPatch := false
	for _, e := range entries {
		if e.Type == EntryTypeTool && e.ToolName == "apply_patch" {
			foundApplyPatch = true
			break
		}
	}
	if !foundApplyPatch {
		t.Error("no apply_patch tool entry found — custom_tool_call handling is broken")
		for i, e := range entries {
			t.Logf("  entry[%d]: type=%s name=%q detail=%q content=%q", i, e.Type, e.ToolName, e.ToolDetail, truncate(e.Content, 60))
		}
	}

	if assistantEntries < 1 {
		t.Errorf("expected at least 1 assistant entry, got %d", assistantEntries)
	}
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "..."
}

